 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8">
   <meta name="viewport" content="width=device-width, initial-scale=1.0">
   <title>Notification Preferences</title>
   <style>
     :root {
       color-scheme: dark;
       --bg: #0b1120;
       --panel: rgba(15, 23, 42, 0.9);
       --panel-border: rgba(148, 163, 184, 0.18);
       --text: #e5e7eb;
       --muted: #94a3b8;
       --accent: #8b5cf6;
       --accent-strong: #a78bfa;
       --accent-soft: rgba(139, 92, 246, 0.16);
       --shadow: 0 24px 60px rgba(2, 6, 23, 0.55);
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 24px;
       font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       background:
         radial-gradient(circle at top, rgba(139, 92, 246, 0.22), transparent 30%),
         linear-gradient(180deg, #020617 0%, #0f172a 100%);
       color: var(--text);
     }

     .card {
       width: min(100%, 520px);
       padding: 32px;
       border: 1px solid var(--panel-border);
       border-radius: 24px;
       background: var(--panel);
       box-shadow: var(--shadow);
       backdrop-filter: blur(14px);
     }

     h1 {
       margin: 0 0 10px;
       font-size: clamp(1.75rem, 4vw, 2.25rem);
       line-height: 1.1;
     }

     p {
       margin: 0 0 28px;
       color: var(--muted);
       line-height: 1.6;
     }

     form {
       display: grid;
       gap: 24px;
     }

     .form-field {
       padding: 20px;
       border: 1px solid rgba(148, 163, 184, 0.16);
       border-radius: 18px;
       background: rgba(15, 23, 42, 0.72);
     }

     fieldset {
       margin: 0;
       padding: 0;
       border: 0;
     }

     legend {
       margin-bottom: 14px;
       font-size: 1.05rem;
       font-weight: 600;
     }

     .radio-option {
       display: flex;
       align-items: center;
       gap: 14px;
       padding: 14px 16px;
       border: 1px solid transparent;
       border-radius: 14px;
       cursor: pointer;
       transition: background-color 0.2s ease, border-color 0.2s ease, transform 0.2s ease;
     }

     .radio-option + .radio-option {
       margin-top: 10px;
     }

     .radio-option:hover {
       background: rgba(30, 41, 59, 0.8);
       border-color: rgba(148, 163, 184, 0.18);
       transform: translateY(-1px);
     }

     input[type="radio"] {
       margin: 0;
       accent-color: var(--accent-strong);
       transform: scale(1.15);
     }

     .radio-option span {
       font-size: 0.98rem;
     }

     button {
       width: 100%;
       border: 0;
       border-radius: 14px;
       padding: 14px 18px;
       font: inherit;
       font-weight: 700;
       color: #f8fafc;
       background: linear-gradient(135deg, var(--accent) 0%, var(--accent-strong) 100%);
       cursor: pointer;
       box-shadow: 0 14px 30px rgba(139, 92, 246, 0.32);
       transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
     }

     button:hover {
       transform: translateY(-1px);
       filter: brightness(1.04);
       box-shadow: 0 18px 34px rgba(139, 92, 246, 0.38);
     }

     button:active {
       transform: translateY(0);
     }

     .message {
       min-height: 1.5rem;
       margin: 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     .message.success {
       color: #c4b5fd;
     }

     @media (max-width: 480px) {
       .card {
         padding: 24px;
       }
     }
   </style>
 </head>
 <body>
   <main class="card">
     <h1>Notification Preferences</h1>
     <p>Select the single notification method you prefer for updates and alerts.</p>

     <form id="notification-form">
       <div class="form-field">
         <fieldset>
           <legend>How do you prefer to receive notifications?</legend>

           <label class="radio-option" for="email">
             <input id="email" type="radio" name="notificationPreference" value="Email" required>
             <span>Email</span>
           </label>

           <label class="radio-option" for="sms">
             <input id="sms" type="radio" name="notificationPreference" value="SMS">
             <span>SMS</span>
           </label>

           <label class="radio-option" for="push">
             <input id="push" type="radio" name="notificationPreference" value="Push Notifications">
             <span>Push Notifications</span>
           </label>
         </fieldset>
       </div>

       <button type="submit">Submit</button>
       <p id="message" class="message" aria-live="polite"></p>
     </form>
   </main>

   <script>
     const form = document.getElementById("notification-form");
     const message = document.getElementById("message");

     form.addEventListener("submit", function (event) {
       event.preventDefault();

       const formData = new FormData(form);
       const preference = formData.get("notificationPreference");

       message.textContent = "Preference saved: " + preference + ".";
       message.classList.add("success");
     });
   </script>
 </body>
